mber() over (partition by account_id order by 1) =1 and account_id is not null) AM on cast(AM.account_id as string) = cast(GADS.ACCOUNT_ID as string) left join ( select upper(CAMPAIGN_NAME) campaign_name ,Commonsku ,upper(Spend_Type) Spend_Type ,upper(channel) Channel from `MapleMonk.Google_Campaigns_Category_Ma` qualify row_number() over (partition by lower(CAMPAIGN_NAME), lower(CHANNEL) order by 1) =1 ) CM on lower(trim(GADS.CAMPAIGN_NAME)) = lower(trim(CM.campaign_name)) left join (select commonsku skucode, name, category, category_code sub_category, category_code, MRP, TAX_RATE from maplemonk.final_sku_master qualify row_number() over (partition by lower(ifnull(trim(COMMONSKU),\'\')) order by lower(ifnull(trim(COMMONSKU),\'\')) desc) = 1 ) p on lower(coalesce(trim(CM.Commonsku),REGEXP_EXTRACT(GADS.CAMPAIGN_NAME, r\'_([^_]{4,})_$\'))) = lower(p.skucode) Union ALL select ACCOUNT_NAME ,\'E-COM\' BUSINESS_SEGMENT ,\'INDIA\' Region ,CHANNEL Marketplace ,PROFILEID ,CAMPAIGN_NAME ,CAMPAIGNID ,adGroupName ,AdGroupId ,ADID ,AD_NAME ,DATE ,CAMPAIGN_TYPE ,AD_STRENGTH ,AD_NETWORK_TYPE ,AD_URL ,DAY_OF_WEEK ,YEAR1 ,MONTH1 ,CHANNEL ,ACCOUNT ,case when lower(CAMPAIGN_TYPE) like \'%brand%\' then \'BRAND\' else coalesce(p.Commonsku,\'MAPPING NA\') end Commonsku ,case when lower(CAMPAIGN_TYPE) like \'%brand%\' then \'BRAND\' else coalesce(p.name, \'MAPPING NA\') end Product_Name_Final ,case when lower(CAMPAIGN_TYPE) like \'%brand%\' then \'BRAND\' else coalesce(p.category,\'MAPPING NA\') end Category ,case when lower(CAMPAIGN_TYPE) like \'%brand%\' then \'BRAND\' else coalesce(p.sub_category,\'MAPPING NA\') end Sub_Category ,CLICKS ,SPEND ,IMPRESSIONS ,CONVERSIONS ,ADSALES ,ADD_TO_CARTS ,ADD_TO_CART_VALUE ,LANDING_PAGE_VIEWS ,Initiate_checkouts ,Initiate_checkouts_value ,ADUNITS FROM maplemonk.KA_AMAZONADS_MARKETING AA left join (select MARKETPLACE_SKU skucode, name, category, category_code sub_category, category_code, MRP, commonsku, TAX_RATE from (select * from maplemonk.final_s