 \'%pca%\' then \'BRAND\' else coalesce(p.Commonsku,\'MAPPING NA\') end Commonsku ,case when lower(CAMPAIGN_TYPE) like \'%pca%\' then \'BRAND\' else coalesce(p.name, \'MAPPING NA\') end Product_Name_Final ,case when lower(CAMPAIGN_TYPE) like \'%pca%\' then \'BRAND\' else coalesce(p.category,\'MAPPING NA\') end Category ,case when lower(CAMPAIGN_TYPE) like \'%pca%\' then \'BRAND\' else coalesce(p.sub_category,\'MAPPING NA\') end Sub_Category ,CLICKS ,SPEND ,IMPRESSIONS ,CONVERSIONS ,ADSALES ,ADD_TO_CARTS ,ADD_TO_CART_VALUE ,LANDING_PAGE_VIEWS ,Initiate_checkouts ,Initiate_checkouts_value ,null as ADUNITS FROM MapleMonk.ka_flipkart_ads_fact_items FA left join (select MARKETPLACE_SKU skucode, name, category, category_code sub_category, category_code, MRP, commonsku, TAX_RATE from (select * from maplemonk.final_sku_master where lower(data_source) like \'%flipkart%\') qualify row_number() over (partition by lower(ifnull(trim(MARKETPLACE_SKU),\'\')) order by lower(ifnull(trim(COMMONSKU),\'\')) desc) = 1 ) p on lower(trim(FA.FSN_ID)) = lower(p.skucode) ; CREATE OR REPLACE TABLE maplemonk.KA_MARKETING_CONSOLIDATED AS select a.ACCOUNT_NAME ,a.ACCOUNT_ID ,a.REGION ,a.MARKETPLACE ,a.CAMPAIGN_NAME ,a.CAMPAIGN_ID ,a.ADSET_NAME ,a.ADSET_ID ,a.AD_ID ,a.AD_NAME ,coalesce(a.DATE,b.date) DATE ,a.AD_TYPE ,a.AD_STRENGTH ,a.AD_NETWORK_TYPE ,a.AD_URL ,a.DAY_OF_WEEK ,a.YEAR1 ,a.MONTH1 ,upper(coalesce(a.CHANNEL, b.channel)) CHANNEL ,a.ACCOUNT ,a.commonsku ,a.Product_Name_Final ,a.Category ,a.Sub_Category ,a.CLICKS ,a.SPEND ,a.IMPRESSIONS ,a.CONVERSIONS ,a.CONVERSION_VALUE ,a.ADUNITS ,a.ADD_TO_CARTS ,a.ADD_TO_CART_VALUE ,a.LANDING_PAGE_VIEWS ,a.INITIATE_CHECKOUTS ,a.INITIATE_CHECKOUTS_VALUE ,b.campaign_name website_campaign_name ,safe_divide(website_revenue, count(1) over (partition by coalesce(a.date,b.date) ,lower(coalesce(a.campaign_name,b.campaign_name)) ,lower(coalesce(a.channel,b.channel)) ) ) website_revenue from maplemonk.KA_MARKETING_CONSOLIDATED_INTERMEDIATE a full outer join (select cast(order_timestamp as date) date ,final_utm_campaign campaign_name ,upper(case when lower(final_utm_channel) like any (\'%paid social%\',\'%facebook%\', \'%instagram%\',\'%ig%\',\'%fb%\') then \'Facebook\' when lower(final_utm_channel) like (\'%google%\') then \'Google\' end) channel ,sum(total_sales) website_revenue from maplemonk.KA_SHOPIFY_FACT_ITEMS where final_utm_channel is not null group by 1,2,3 ) b on lower(a.campaign_name) = lower(b.campaign_name) and a.date = b.date and lower(a.channel) = lower(b.channel);",
